// allocatable per node (3 identical nodes)
const nodes = [
  { name: 'n1', cpu: 2000, mem: 4096 },
  { name: 'n2', cpu: 2000, mem: 4096 },
  { name: 'n3', cpu: 2000, mem: 4096 },
];
// desired pods: each entry is { name, cpu(m), mem(Mi), replicas }
const deploys = [
  { name: 'api',   cpu: 500, mem: 1024, replicas: 6 },
  { name: 'worker',cpu: 750, mem: 1024, replicas: 4 },
  { name: 'redis', cpu: 250, mem: 512,  replicas: 1 },
];
// expand to a flat, deterministic pod list (stable order)
const pods = [];
for (const d of deploys)
  for (let i = 0; i < d.replicas; i++)
    pods.push({ name: d.name + '-' + i, cpu: d.cpu, mem: d.mem });
// first-fit: place each pod on the first node with room (requests model)
const free = nodes.map(n => ({ name: n.name, cpu: n.cpu, mem: n.mem }));
let unscheduled = 0;
for (const p of pods) {
  const slot = free.find(f => f.cpu >= p.cpu && f.mem >= p.mem);
  if (slot) { slot.cpu -= p.cpu; slot.mem -= p.mem; }
  else unscheduled++;
}
const totalCpuReq = pods.reduce((s, p) => s + p.cpu, 0);
const totalCpuCap = nodes.reduce((s, n) => s + n.cpu, 0);
console.log('pods=' + pods.length + ' cpuReq=' + totalCpuReq + ' cpuCap=' + totalCpuCap + ' unscheduled=' + unscheduled);
console.log(unscheduled === 0 ? 'FITS' : 'PENDING');
